module GameRoomGames
  class Scrabble
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:crossword, GameRoomRules.translate("Build one crossword together"),
            GameRoomRules.translate("Two to four people play on a 15-by-15 board, using letter tiles to score words. There are no bots in this game. Everyone starts with seven tiles on a private rack and refills towards seven after playing, while tiles remain in the bag. The first word must cross the centre, H8. Later moves must connect to the existing crossword."),
            GameRoomRules.translate("In one move, place your new letters in a single row or column. Existing letters may fill the spaces between them, but the completed line cannot have empty gaps. Words read left to right or top to bottom, never diagonally. You may extend a word, cross it, or place letters beside it to make several shorter words. Every newly created word must be valid, not just the longest one. Accepted letters stay in place for the rest of the game.")),
          rule_section(:draft, GameRoomRules.translate("Watch a word being built"),
            GameRoomRules.translate("Other players and observers can see the letters you place before you submit your word. Moving or removing a draft tile updates their boards without moving their cursors. Only letters already placed on the board are shared, not the rest of your rack. This is a preview: points and the permanent board change only after the move is accepted. Passing, a timeout or the end of the game removes the unfinished draft.")),
          rule_section(:dictionary, GameRoomRules.translate("The chosen language decides which words count"),
            GameRoomRules.translate("Choose Polish or English for the tiles and dictionary, independently of your interface language. Polish uses the SJP data dated 2026-09-01; English uses Wordnik data dated 2021-07-29. These are the local word lists supplied with Power Games, not the official OSPS, NWL, Collins or QC lists. Words contain two to fifteen letters and are checked against the selected list when you submit the move."),
            GameRoomRules.translate("Each language has 100 tiles, including two blanks, but different letter quantities and values. A blank can represent a letter you choose when placing it. It always scores zero and keeps that chosen letter after the move is accepted. It cannot later be changed into another letter or recovered from the board.")),
          rule_section(:points, GameRoomRules.translate("How a move earns points"),
            GameRoomRules.translate("For each new word, add the values of all its letters, including letters already on the board. A newly covered letter bonus doubles or triples that tile's value. After letter bonuses, apply the word bonuses to the whole word. Several word multipliers multiply together. For example, two double-word fields make the word worth four times its letter total."),
            GameRoomRules.translate("A letter shared by two new words scores in both. Bonuses work only on the move that first covers them; extending a word later does not activate its old bonuses again. A blank still scores zero on a letter bonus, but can activate a word bonus. Using all seven rack tiles in one move adds 50 points after the word totals have been calculated.")),
          rule_section(:alternatives, GameRoomRules.translate("You may exchange or pass instead"),
            GameRoomRules.translate("Exchange one to seven tiles only when at least eight are left in the bag. Select the tiles to return and confirm the exchange; this uses your turn. In this version, returned tiles go back into the bag before it is shuffled and replacements are drawn, so you may get a returned tile again. You can also pass without exchanging. Neither choice places an unfinished draft on the board.")),
          rule_section(:invalid, GameRoomRules.translate("What happens to an unrecognised word"),
            GameRoomRules.translate("Invalid word offers six policies. Choose whether an invalid submission lets you correct the move or ends your turn, and whether it costs zero, 5 or 10 points. The default is correction without a penalty. One submitted attempt incurs at most one penalty, even if several words are invalid. The draft returns to the rack and does not use any board bonuses."),
            GameRoomRules.translate("Placement errors, such as a disconnected word or a gap, are not penalised as invalid words. Y previews the words and their points but deliberately does not consult the dictionary. A preview is therefore not a guarantee that a word will be accepted. Dictionary checking happens only when you submit.")),
          rule_section(:ending, GameRoomRules.translate("The last tiles and the final score"),
            GameRoomRules.translate("Thinking time is zero for no limit, or 20\u2013600 seconds per turn. Choosing a blank and correcting a word use the same turn time. Timeout cancels the unsubmitted draft and passes; it does not draw tiles or charge a separate point penalty."),
            GameRoomRules.translate("The game ends when someone empties their rack and the bag is empty. It also ends as blocked when exchanging is unavailable and three complete circuits pass without a tile being placed. A legal word worth zero still breaks this sequence. At the end, subtract each player's remaining tile values. If a player went out, they also gain the other players' remaining values; a blocked game has no such bonus. Blanks are worth zero. The highest adjusted score wins, with a shared result if tied.")),
          rule_section(:controls, GameRoomRules.translate("Game keyboard shortcuts"),
            GameRoomRules.translate("Arrows: move around the board."),
            GameRoomRules.translate("Enter: on an empty square, choose a rack tile, then place it; a blank asks for its letter."),
            GameRoomRules.translate("Backspace: remove your unsubmitted tile under the cursor."),
            GameRoomRules.translate("Z: clear the whole draft."),
            GameRoomRules.translate("F: submit the draft."),
            GameRoomRules.translate("Escape: cancel the current tile or exchange choice."),
            GameRoomRules.translate("C: read the rack."),
            GameRoomRules.translate("I: cycle receipt, alphabetic and vowel-first order after clearing the draft."),
            GameRoomRules.translate("Y: preview the words and their points."),
            GameRoomRules.translate("L: browse played words."),
            GameRoomRules.translate("G: choose tiles to exchange; Space selects and Enter confirms in that list."),
            GameRoomRules.translate("P: pass your turn."),
            GameRoomRules.translate("E: read tile counts."),
            GameRoomRules.translate("S: read scores."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("1: read rack position 1, without placing it."),
            GameRoomRules.translate("2: read rack position 2, without placing it."),
            GameRoomRules.translate("3: read rack position 3, without placing it."),
            GameRoomRules.translate("4: read rack position 4, without placing it."),
            GameRoomRules.translate("5: read rack position 5, without placing it."),
            GameRoomRules.translate("6: read rack position 6, without placing it."),
            GameRoomRules.translate("7: read rack position 7, without placing it."),
            GameRoomRules.translate("Shift+1: place rack tile 1 on the current square; a blank asks for its letter."),
            GameRoomRules.translate("Shift+2: place rack tile 2 on the current square; a blank asks for its letter."),
            GameRoomRules.translate("Shift+3: place rack tile 3 on the current square; a blank asks for its letter."),
            GameRoomRules.translate("Shift+4: place rack tile 4 on the current square; a blank asks for its letter."),
            GameRoomRules.translate("Shift+5: place rack tile 5 on the current square; a blank asks for its letter."),
            GameRoomRules.translate("Shift+6: place rack tile 6 on the current square; a blank asks for its letter."),
            GameRoomRules.translate("Shift+7: place rack tile 7 on the current square; a blank asks for its letter."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:goal, "C\u00EDl hry a hrac\u00ED deska",
              "Ve Scrabble z\u00EDsk\u00E1v\u00E1\u0161 body skl\u00E1d\u00E1n\u00EDm slov z p\u00EDsmen. V\u0161ichni spole\u010Dn\u011B roz\u0161i\u0159ujete jednu k\u0159\u00ED\u017Eovku, ale ka\u017Ed\u00FD boduje za vlastn\u00ED tahy. Na konci vyhraje nejvy\u0161\u0161\u00ED sk\u00F3re.",
              "Hraj\u00ED dva a\u017E \u010Dty\u0159i hr\u00E1\u010Di. Ka\u017Ed\u00FD m\u00E1 sedm kamen\u016F v z\u00E1sobn\u00EDku; C je p\u0159e\u010Dte i s bodov\u00FDmi hodnotami. Po p\u0159ijat\u00E9m tahu si dopln\u00ED\u0161 z\u00E1sobn\u00EDk do sedmi, dokud jsou kameny v s\u00E1\u010Dku.",
              "Deska m\u00E1 patn\u00E1ct sloupc\u016F A a\u017E O a patn\u00E1ct \u0159ad 1 a\u017E 15. Proch\u00E1z\u00ED\u0161 ji \u0161ipkami. Nejprve usly\u0161\u00ED\u0161 p\u00EDsmeno nebo pr\u00E1zdn\u00E9 pole, potom sou\u0159adnice. N\u011Bkter\u00E1 voln\u00E1 pole nav\u00EDc nesou bodovou pr\u00E9mii."),
            rule_section(:placement, "Kam sm\u00ED\u0161 polo\u017Eit slovo",
              "Prvn\u00ED slovo mus\u00ED proj\u00EDt st\u0159edem H8. Dal\u0161\u00ED navazuj\u00ED na dosavadn\u00ED k\u0159\u00ED\u017Eovku: m\u016F\u017Ee\u0161 slovo prodlou\u017Eit, p\u0159ek\u0159\u00ED\u017Eit nov\u00FDm nebo p\u0159ilo\u017Eit p\u00EDsmena vedle a vytvo\u0159it n\u011Bkolik slov sou\u010Dasn\u011B.",
              "Ka\u017Ed\u00FD tah mus\u00ED splnit tyto podm\u00EDnky:",
              "- V\u0161echny nov\u011B polo\u017Een\u00E9 kameny le\u017E\u00ED v jedn\u00E9 \u0159ad\u011B nebo sloupci. \u010Cte se zleva doprava nebo shora dol\u016F.",
              "- Hotov\u00E9 slovo nem\u00E1 mezi p\u00EDsmeny mezery. M\u016F\u017Ee ale uvnit\u0159 vyu\u017E\u00EDvat d\u0159\u00EDve polo\u017Een\u00E1 p\u00EDsmena.",
              "- Ka\u017Ed\u00E9 nov\u00E9 slovo m\u00E1 alespo\u0148 dv\u011B p\u00EDsmena a mus\u00ED b\u00FDt ve slovn\u00EDku. To plat\u00ED i pro kr\u00E1tk\u00E1 slova vznikl\u00E1 nap\u0159\u00ED\u010D, nejen pro hlavn\u00ED slovo.",
              "Kameny z p\u0159ijat\u00FDch tah\u016F z\u016Fst\u00E1vaj\u00ED na desce. Nesm\u00ED\u0161 je p\u0159esouvat ani br\u00E1t zp\u011Bt, m\u016F\u017Ee\u0161 je v\u0161ak zapojit do dal\u0161\u00EDch slov."),
            rule_section(:play, "Skl\u00E1d\u00E1n\u00ED a potvrzen\u00ED tahu",
              "\u0160ipkami najdi voln\u00E9 pole a stiskni Enter. Ze seznamu kamen\u016F v z\u00E1sobn\u00EDku vyber p\u00EDsmeno \u0161ipkami a potvr\u010F Enterem. K\u00E1men se polo\u017E\u00ED, ale tah t\u00EDm je\u0161t\u011B nen\u00ED odevzdan\u00FD.",
              "Stejn\u011B p\u0159idej dal\u0161\u00ED p\u00EDsmena. Chybn\u00FD k\u00E1men vezme\u0161 zp\u011Bt kl\u00E1vesou Backspace na jeho poli. Z odstran\u00ED v\u0161echny kameny p\u0159ipraven\u00E9 v tomto tahu a umo\u017En\u00ED za\u010D\u00EDt znovu.",
              "Kl\u00E1vesa Y p\u0159e\u010Dte p\u0159ipraven\u00E1 slova a p\u0159edb\u011B\u017En\u00E9 body, nikoli jejich platnost ve slovn\u00EDku. Hotov\u00FD tah ode\u0161li pomoc\u00ED F. Teprve pak se slova ov\u011B\u0159\u00ED, kameny z\u016Fstanou na desce, dostane\u0161 body a tah skon\u010D\u00ED.",
              "Nezn\u00E1m\u00E9 slovo se ozn\u00E1m\u00ED a p\u0159ipraven\u00E9 kameny se vr\u00E1t\u00ED do z\u00E1sobn\u00EDku. B\u011B\u017En\u011B sm\u00ED\u0161 ve stejn\u00E9m tahu zkusit n\u011Bco jin\u00E9ho bez ztr\u00E1ty bod\u016F. Tak\u00E9 nespr\u00E1vn\u00E9 um\u00EDst\u011Bn\u00ED, nap\u0159\u00EDklad mezera nebo chyb\u011Bj\u00EDc\u00ED spojen\u00ED s k\u0159\u00ED\u017Eovkou, vy\u017Eaduje opravu."),
            rule_section(:blanks, "Pr\u00E1zdn\u00E9 kameny",
              "Pr\u00E1zdn\u00FD k\u00E1men zastoup\u00ED libovoln\u00E9 p\u00EDsmeno. P\u0159i polo\u017Een\u00ED se otev\u0159e volba: \u0161ipkami ur\u010Di p\u00EDsmeno a potvr\u010F Enterem. Pak ho zapoj\u00ED\u0161 do slova jako b\u011B\u017En\u00FD k\u00E1men.",
              "Bodov\u00E1 hodnota je v\u017Edy nula a po p\u0159ijet\u00ED tahu vybran\u00E9 p\u00EDsmeno z\u016Fstane do konce partie. V sad\u011B jsou dva pr\u00E1zdn\u00E9 kameny."),
            rule_section(:points, "Bodov\u00E1n\u00ED",
              "Boduje ka\u017Ed\u00E9 slovo vznikl\u00E9 v tahu. Se\u010Dtou se hodnoty v\u0161ech jeho p\u00EDsmen, v\u010Detn\u011B star\u0161\u00EDch na desce. Pat\u0159\u00ED-li nov\u00E9 p\u00EDsmeno z\u00E1rove\u0148 do vodorovn\u00E9ho a svisl\u00E9ho slova, zapo\u010D\u00EDt\u00E1 se v obou.",
              "Pr\u00E9miov\u00E9 pole se uplatn\u00ED pouze p\u0159i prvn\u00EDm polo\u017Een\u00ED kamene:",
              "- P\u00EDsmenn\u00E1 pr\u00E9mie zdvojn\u00E1sob\u00ED \u010Di ztrojn\u00E1sob\u00ED tento k\u00E1men, potom se p\u0159i\u010Dtou ostatn\u00ED p\u00EDsmena.",
              "- Slovn\u00ED pr\u00E9mie n\u00E1sob\u00ED cel\u00FD v\u00FDsledek slova dv\u011Bma \u010Di t\u0159emi. V\u00EDce n\u00E1sobi\u010D\u016F se n\u00E1sob\u00ED navz\u00E1jem: dv\u011B dvojn\u00E1sobn\u00E9 pr\u00E9mie znamenaj\u00ED \u010Dty\u0159n\u00E1sobek.",
              "Pr\u00E1zdn\u00FD k\u00E1men z\u016Fstane na p\u00EDsmenn\u00E9 pr\u00E9mii za nulu, slovn\u00ED pr\u00E9mii ale spust\u00ED. P\u0159i pozd\u011Bj\u0161\u00EDm prodlu\u017Eov\u00E1n\u00ED slova se ji\u017E zakryt\u00E1 pr\u00E9miov\u00E1 pole znovu nepo\u010D\u00EDtaj\u00ED.",
              "Za pou\u017Eit\u00ED v\u0161ech sedmi kamen\u016F v jednom tahu p\u0159id\u00E1\u0161 50 bod\u016F. P\u0159i\u010Dtou se a\u017E po vyhodnocen\u00ED slov a d\u00E1l se nen\u00E1sob\u00ED. Sk\u00F3re p\u0159e\u010Dte S."),
            rule_section(:exchange, "V\u00FDm\u011Bna a vynech\u00E1n\u00ED",
              "M\u00EDsto skl\u00E1d\u00E1n\u00ED m\u016F\u017Ee\u0161 ob\u011Btovat tah v\u00FDm\u011Bn\u011B. Stiskni G, proch\u00E1zej kameny \u0161ipkami a mezern\u00EDkem ozna\u010D ty k v\u00FDm\u011Bn\u011B. Enter ji potvrd\u00ED, Escape zru\u0161\u00ED.",
              "Vym\u011Bnit lze jeden a\u017E sedm kamen\u016F, pokud v s\u00E1\u010Dku zb\u00FDv\u00E1 nejm\u00E9n\u011B osm. Odevzdan\u00E9 se vracej\u00ED p\u0159ed dobr\u00E1n\u00EDm, tak\u017Ee m\u016F\u017Ee\u0161 n\u011Bkter\u00FD znovu dostat. Po\u010Dty v s\u00E1\u010Dku a z\u00E1sobn\u00EDc\u00EDch p\u0159e\u010Dte E.",
              "Kl\u00E1vesa P vynech\u00E1 tah bez slova i bez v\u00FDm\u011Bny. M\u00E1\u0161-li u\u017E na desce p\u0159ipraven\u00E9 kameny, hra se p\u0159ed vynech\u00E1n\u00EDm \u010Di v\u00FDm\u011Bnou zept\u00E1, zda je sm\u00ED vz\u00EDt zp\u011Bt."),
            rule_section(:ending, "Konec a kone\u010Dn\u00E9 sk\u00F3re",
              "Partie m\u016F\u017Ee skon\u010Dit dv\u011Bma zp\u016Fsoby:",
              "- S\u00E1\u010Dek je pr\u00E1zdn\u00FD a n\u011Bkdo zahraje v\u0161echny sv\u00E9 kameny. Hra kon\u010D\u00ED po tomto tahu.",
              "- V\u00FDm\u011Bna u\u017E nen\u00ED mo\u017En\u00E1 a t\u0159i cel\u00E1 kola tah\u016F nikdo nezahraje slovo. Ka\u017Ed\u00E9 p\u0159ijat\u00E9 slovo toto po\u010D\u00EDt\u00E1n\u00ED p\u0159eru\u0161\u00ED, i kdyby bylo za nula bod\u016F.",
              "Na konci se ka\u017Ed\u00E9mu ode\u010Dte hodnota zbyl\u00FDch kamen\u016F. Hr\u00E1\u010D, kter\u00FD vypr\u00E1zdnil z\u00E1sobn\u00EDk, si nav\u00EDc p\u0159i\u010Dte sou\u010Det zbytk\u016F ostatn\u00EDch. P\u0159i zablokov\u00E1n\u00ED tento bonus nen\u00ED. Pr\u00E1zdn\u00FD k\u00E1men m\u00E1 i v ruce nulu.",
              "Po t\u011Bchto \u00FAprav\u00E1ch vyhraje nejvy\u0161\u0161\u00ED sk\u00F3re. P\u0159i shod\u011B se o v\u00EDt\u011Bzstv\u00ED d\u011Bl\u00EDte."),
            rule_section(:language, "Jazyk a slovn\u00EDk",
              "P\u0159ed hrou m\u016F\u017Ee\u0161 zvolit polsk\u00E1 nebo anglick\u00E1 p\u00EDsmena a slovn\u00EDk. Li\u0161\u00ED se zastoupen\u00ED p\u00EDsmen i jejich hodnoty, v obou sad\u00E1ch je ale sto kamen\u016F.",
              "Polsk\u00E1 hra pou\u017E\u00EDv\u00E1 p\u0159ilo\u017Een\u00FD slovn\u00EDk SJP, anglick\u00E1 Wordnik. Mohou se li\u0161it od turnajov\u00FDch slovn\u00EDk\u016F. O p\u0159ijet\u00ED rozhoduje slovn\u00EDk vybran\u00E9ho jazyka."),
            rule_section(:penalties, "Neplatn\u00E1 slova",
              "V nastaven\u00ED stolu zvol\u00ED\u0161, co ud\u011Bl\u00E1 odm\u00EDtnut\u00ED slova slovn\u00EDkem:",
              "- Povol\u00ED opravu ve stejn\u00E9m tahu, jako v z\u00E1kladn\u00ED h\u0159e.",
              "- Ukon\u010D\u00ED tah; dal\u0161\u00ED hr\u00E1\u010D pokra\u010Duje a tvoje kameny z\u016Fstanou v z\u00E1sobn\u00EDku.",
              "Ob\u011B mo\u017Enosti jsou bez bodov\u00E9ho trestu nebo s ode\u010Dtem 5 \u010Di 10 bod\u016F. Za jedno potvrzen\u00ED F vznikne nejv\u00FD\u0161 jeden trest, i kdy\u017E je neplatn\u00FDch slov v\u00EDce. Chyby um\u00EDst\u011Bn\u00ED, t\u0159eba mezera, se t\u00EDmto trestem nepostihuj\u00ED."),
            rule_section(:time, "\u010Cas na tah",
              "B\u011B\u017En\u011B nen\u00ED \u010Das omezen. Voliteln\u00FD limit p\u0159ed hrou plat\u00ED pro cel\u00FD tah v\u010Detn\u011B volby p\u00EDsmene pr\u00E1zdn\u00E9ho kamene a oprav odm\u00EDtnut\u00FDch slov.",
              "Po vypr\u0161en\u00ED se p\u0159ipraven\u00E9 kameny vr\u00E1t\u00ED do z\u00E1sobn\u00EDku a tah skon\u010D\u00ED vynech\u00E1n\u00EDm. Samotn\u00E9 vypr\u0161en\u00ED \u010Dasu dal\u0161\u00ED bodov\u00FD trest nem\u00E1."),
            rule_section(:personal, "Z\u00E1sobn\u00EDk a hl\u00E1\u0161en\u00ED pokl\u00E1dan\u00FDch p\u00EDsmen",
              "Kdy\u017E nem\u00E1\u0161 nic p\u0159ipraven\u00E9ho na desce, I m\u011Bn\u00ED \u0159azen\u00ED z\u00E1sobn\u00EDku: po\u0159ad\u00ED p\u0159ijet\u00ED, abecedn\u011B nebo samohl\u00E1sky nap\u0159ed. \u010C\u00EDsla 1 a\u017E 7 p\u0159e\u010Dtou jednotliv\u00E9 pozice. Shift s \u010D\u00EDslem dan\u00FD k\u00E1men rovnou polo\u017E\u00ED na pole pod kurzorem.",
              "Na desce m\u016F\u017Ee\u0161 sledovat i rozpracovan\u00FD tah druh\u00E9ho hr\u00E1\u010De. Chce\u0161-li sly\u0161et hl\u00E1\u0161en\u00ED p\u0159idan\u00FDch a odebran\u00FDch p\u00EDsmen, zapni je pomoc\u00ED Ctrl+P. Opakov\u00E1n\u00EDm je vypne\u0161."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "\u0160ipky: proch\u00E1zet desku nebo otev\u0159en\u00FD seznam.",
              "Enter: vybrat a polo\u017Eit k\u00E1men; p\u0159i v\u00FDm\u011Bn\u011B potvrdit ozna\u010Den\u00E9.",
              "Backspace: vz\u00EDt zp\u011Bt nepotvrzen\u00FD k\u00E1men pod kurzorem.",
              "Z: odstranit v\u0161echny kameny p\u0159ipraven\u00E9ho tahu.",
              "F: potvrdit slo\u017Een\u00E1 slova.",
              "Y: p\u0159e\u010D\u00EDst p\u0159ipraven\u00E1 slova a body bez ov\u011B\u0159en\u00ED slovn\u00EDkem.",
              "Escape: zru\u0161it v\u00FDb\u011Br kamene nebo v\u00FDm\u011Bnu.",
              "C: p\u0159e\u010D\u00EDst z\u00E1sobn\u00EDk.",
              "I: zm\u011Bnit \u0159azen\u00ED, pokud je\u0161t\u011B nic neskl\u00E1d\u00E1\u0161.",
              "G: vybrat kameny k v\u00FDm\u011Bn\u011B.",
              "Mezern\u00EDk v seznamu v\u00FDm\u011Bny: ozna\u010Dit \u010Di odzna\u010Dit k\u00E1men.",
              "P: vynechat tah.",
              "E: p\u0159e\u010D\u00EDst po\u010Dty kamen\u016F v z\u00E1sobn\u00EDc\u00EDch a s\u00E1\u010Dku.",
              "L: prohl\u00E9dnout zahran\u00E1 slova.",
              "S: p\u0159e\u010D\u00EDst sk\u00F3re.",
              "T: ozn\u00E1mit, kdo je na tahu.",
              "1: p\u0159e\u010D\u00EDst prvn\u00ED k\u00E1men z\u00E1sobn\u00EDku.",
              "2: p\u0159e\u010D\u00EDst druh\u00FD k\u00E1men z\u00E1sobn\u00EDku.",
              "3: p\u0159e\u010D\u00EDst t\u0159et\u00ED k\u00E1men z\u00E1sobn\u00EDku.",
              "4: p\u0159e\u010D\u00EDst \u010Dtvrt\u00FD k\u00E1men z\u00E1sobn\u00EDku.",
              "5: p\u0159e\u010D\u00EDst p\u00E1t\u00FD k\u00E1men z\u00E1sobn\u00EDku.",
              "6: p\u0159e\u010D\u00EDst \u0161est\u00FD k\u00E1men z\u00E1sobn\u00EDku.",
              "7: p\u0159e\u010D\u00EDst sedm\u00FD k\u00E1men z\u00E1sobn\u00EDku.",
              "Shift+1: polo\u017Eit prvn\u00ED k\u00E1men na pole pod kurzorem.",
              "Shift+2: polo\u017Eit druh\u00FD k\u00E1men na pole pod kurzorem.",
              "Shift+3: polo\u017Eit t\u0159et\u00ED k\u00E1men na pole pod kurzorem.",
              "Shift+4: polo\u017Eit \u010Dtvrt\u00FD k\u00E1men na pole pod kurzorem.",
              "Shift+5: polo\u017Eit p\u00E1t\u00FD k\u00E1men na pole pod kurzorem.",
              "Shift+6: polo\u017Eit \u0161est\u00FD k\u00E1men na pole pod kurzorem.",
              "Shift+7: polo\u017Eit sedm\u00FD k\u00E1men na pole pod kurzorem.",
              "Ctrl+P: p\u0159epnout hl\u00E1\u0161en\u00ED pokl\u00E1dan\u00FDch a odeb\u00EDran\u00FDch p\u00EDsmen.")
          ]
        when "en"
          [
            rule_section(:goal, "Words and points",
              "Build words from letter tiles on a shared crossword board. Every player scores their own words; the highest final score wins.",
              "Two to four players receive seven tiles each. C reads your rack and the letters' values. After an accepted move, the game refills your rack to seven while tiles remain in the bag.",
              "The board has fifteen columns, A to O, and fifteen rows, 1 to 15. Explore it with the arrows. A square is read as its letter, or empty, followed by its coordinates. Some empty squares also have bonuses that increase a move's score."),
            rule_section(:placement, "Where words can go",
              "The first word must cover the centre square, H8. Later moves must connect to the crossword already on the board. Extend a word, cross it with another, or lay tiles alongside it to make several words.",
              "Every move must satisfy these rules:",
              "- All tiles you add this turn go in one row or one column. Words read from left to right or from top to bottom.",
              "- The completed word cannot have gaps. Existing letters can fill spaces between your new tiles.",
              "- Every new word must have at least two letters and be in the game's dictionary. This includes short crossing words, not only the main word you intended.",
              "Once a move is accepted, those letters stay in place. You cannot take them back or move them, but may use them in later words."),
            rule_section(:play, "Laying and submitting tiles",
              "Move to an empty square with the arrows and press Enter to open your available tiles. Choose a tile with the arrows and press Enter again. It appears on the square, but your turn is not yet submitted.",
              "Place the rest of your letters in the same way. To correct a mistake, return to a tile added this turn and press Backspace to remove it. Z takes back the whole draft so you can start again.",
              "Y reads the draft words and their estimated score without checking the dictionary. When ready, press F to submit. The words are checked, and an accepted move fixes the tiles in place, scores the words and ends your turn.",
              "If a word is not recognised, you hear which one and the draft tiles return to your rack. Under the default rules you can try again in the same turn without losing points. Placement errors, such as a gap or no connection to existing tiles, must also be corrected."),
            rule_section(:blanks, "Blanks",
              "A blank can stand for any letter. When placing one, choose its letter from the extra list with the arrows and confirm with Enter.",
              "A blank is always worth zero, and keeps its assigned letter for the rest of the game once the move is accepted. There are two blanks in the set."),
            rule_section(:points, "Scoring a move",
              "Score every word formed by your move, adding all its letter values, including tiles already on the board. A new tile used in both a horizontal and vertical word counts in both.",
              "A bonus square applies only when a tile is first placed on it:",
              "- A letter bonus doubles or triples that tile's value before you add the other letters.",
              "- A word bonus doubles or triples the whole word. Multiple word bonuses multiply together: two double-word squares make the word worth four times its normal score.",
              "A blank on a letter bonus remains zero. On a word bonus it still doubles or triples the whole word. Extending a word later does not reactivate bonuses under old tiles.",
              "Using all seven rack tiles in one turn adds 50 points after the words are scored. This bonus is not multiplied. Press S to hear scores."),
            rule_section(:exchange, "Exchanging or passing",
              "Instead of making a word, you may spend your turn exchanging tiles. Press G, browse the tiles with the arrows and mark unwanted ones with Space. Enter confirms; Escape cancels.",
              "You may exchange one to seven tiles if at least eight remain in the bag. Your returned tiles go into the bag before you draw, so you might receive one again. E reads the bag and rack counts.",
              "P passes without playing or exchanging. If you already have a draft on the board, passing or exchanging asks you to confirm taking those tiles back."),
            rule_section(:ending, "Ending the game",
              "The game ends in either of these ways:",
              "- The bag is empty and someone uses every tile in their rack.",
              "- Exchanges are no longer possible and nobody plays a word for three complete rounds of turns. A word interrupts this count even if it scores zero.",
              "Subtract the value of each player's remaining rack from their score. If someone emptied their rack, they also receive the combined value left on everyone else's. There is no such award for a blocked game. Unplayed blanks count as zero.",
              "Compare the adjusted totals. The highest wins; equal highest totals share victory."),
            rule_section(:language, "Tiles and dictionary",
              "Before play, choose Polish or English tiles and dictionary. The letter distribution and values change, but both sets contain 100 tiles.",
              "Polish uses the included SJP dictionary; English uses Wordnik. These may differ from tournament dictionaries. The selected dictionary decides which words are accepted."),
            rule_section(:penalties, "Rejected-word penalties",
              "The table can change what happens when a submitted word is not in the dictionary:",
              "- Allow another attempt, as in the default game.",
              "- End the turn instead, leaving the tiles in the player's rack.",
              "Either approach can have no point penalty or a penalty of 5 or 10 points. A single press of F incurs at most one penalty, even if several words are invalid. Placement errors, such as a gap, do not incur this penalty."),
            rule_section(:time, "Turn time",
              "Turns are normally untimed. The host can set a time limit covering the whole turn, including blank choices and retries after a rejected word.",
              "At timeout, draft tiles return to the rack and the turn ends as a pass. Timeout itself carries no extra point penalty."),
            rule_section(:personal, "Rack order and draft announcements",
              "With no draft tiles placed, I changes rack order: as received, alphabetical, or vowels first. Number keys 1\u20137 read individual positions. Shift with a number places that rack tile straight onto the square at the cursor.",
              "You can follow another player's draft on the board before they submit it. Ctrl+P turns spoken announcements of tiles being placed and removed on or off."),
            rule_section(:controls, "Keyboard shortcuts",
              "Arrows: move around the board or an open list.",
              "Enter: choose and place a tile; confirm marked tiles in the exchange window.",
              "Backspace: remove an unsubmitted tile at the cursor.",
              "Z: take back the whole draft.",
              "F: submit your words.",
              "Y: read draft words and points without a dictionary check.",
              "Escape: cancel tile selection or exchange.",
              "C: read the rack.",
              "I: change rack order when no draft is placed.",
              "G: choose tiles to exchange.",
              "Space in the exchange list: mark or unmark a tile.",
              "P: pass.",
              "E: read rack and bag counts.",
              "L: review played words.",
              "S: read scores.",
              "T: check whose turn it is.",
              "1: read rack tile 1.",
              "2: read rack tile 2.",
              "3: read rack tile 3.",
              "4: read rack tile 4.",
              "5: read rack tile 5.",
              "6: read rack tile 6.",
              "7: read rack tile 7.",
              "Shift+1: place rack tile 1 at the cursor.",
              "Shift+2: place rack tile 2 at the cursor.",
              "Shift+3: place rack tile 3 at the cursor.",
              "Shift+4: place rack tile 4 at the cursor.",
              "Shift+5: place rack tile 5 at the cursor.",
              "Shift+6: place rack tile 6 at the cursor.",
              "Shift+7: place rack tile 7 at the cursor.",
              "Ctrl+P: toggle tile-placement and removal announcements.")
          ]
        when "es"
          [
            rule_section(:goal, "Objetivo y tablero",
              "En Scrabble formas palabras con fichas de letras para ganar puntos. Todos ampl\u00EDan el mismo crucigrama, pero cada jugador punt\u00FAa sus propias palabras. Gana quien tenga m\u00E1s puntos al terminar.",
              "Juegan de dos a cuatro personas, con siete fichas cada una en su atril. C lee tus letras y sus valores. Tras una jugada aceptada, repones hasta siete mientras queden fichas en la bolsa.",
              "El tablero tiene quince columnas, de A a O, y quince filas, del 1 al 15. Recorre las casillas con las flechas: oir\u00E1s primero la letra o que est\u00E1 vac\u00EDa, y despu\u00E9s sus coordenadas. Algunas casillas vac\u00EDas anuncian tambi\u00E9n una bonificaci\u00F3n."),
            rule_section(:placement, "D\u00F3nde formar palabras",
              "La primera palabra debe pasar por el centro, H8. Las siguientes deben conectarse con lo que ya est\u00E9 colocado: puedes alargar una palabra, cruzar otra con ella o poner letras al lado y formar varias palabras.",
              "Cada jugada debe cumplir estas condiciones:",
              "- Todas las fichas nuevas van en una misma fila o columna. Se lee de izquierda a derecha o de arriba abajo.",
              "- La palabra terminada no puede tener huecos. S\u00ED puede contener letras que ya estuvieran en el tablero entre las nuevas.",
              "- Cada palabra nueva debe tener al menos dos letras y estar en el diccionario del juego. Esto incluye las palabras cortas que se formen al cruzar, no solo la principal.",
              "Las letras de las jugadas aceptadas permanecen en su lugar. No se mueven ni se recogen, pero puedes usarlas en palabras posteriores."),
            rule_section(:play, "Colocar letras y confirmar la jugada",
              "Ve con las flechas a una casilla vac\u00EDa donde quieras colocar una letra y pulsa Enter. Se abre tu atril: elige una ficha con las flechas y confirma con Enter. Queda preparada en esa casilla, pero a\u00FAn no has terminado el turno.",
              "Coloca las dem\u00E1s letras del mismo modo. Para corregir una, vuelve a su casilla y pulsa Retroceso. Z retira todas las fichas que hayas a\u00F1adido en este turno para empezar de nuevo.",
              "Y lee las palabras preparadas y su puntuaci\u00F3n prevista, sin consultar a\u00FAn el diccionario. Cuando est\u00E9 todo listo, pulsa F. Entonces se comprueban las palabras; si se aceptan, las fichas quedan en el tablero, recibes los puntos y termina tu turno.",
              "Si el diccionario rechaza una palabra, oir\u00E1s cu\u00E1l es y todas las fichas preparadas volver\u00E1n al atril. Con las reglas habituales puedes intentar otra jugada en ese mismo turno sin perder puntos. Tambi\u00E9n debes corregir una colocaci\u00F3n ilegal, como dejar un hueco o no conectar con el crucigrama."),
            rule_section(:blanks, "Comodines",
              "Una ficha en blanco puede representar cualquier letra. Al colocarla aparece una elecci\u00F3n adicional: elige la letra con las flechas y confirma con Enter. Despu\u00E9s forma palabras como cualquier otra ficha.",
              "Siempre vale cero puntos. Una vez aceptada la jugada, conserva la letra elegida hasta el final. Hay dos fichas en blanco en el juego."),
            rule_section(:points, "Puntuaci\u00F3n",
              "Punt\u00FAas cada palabra formada en tu jugada. Suma todas sus letras, incluidas las que ya estaban en la mesa. Si una letra nueva pertenece a una palabra horizontal y a otra vertical, cuenta en ambas.",
              "Las bonificaciones de una casilla solo se usan cuando se ocupa por primera vez:",
              "- Doble o triple letra multiplica el valor de la ficha colocada all\u00ED. Despu\u00E9s se a\u00F1aden las otras letras de la palabra.",
              "- Doble o triple palabra multiplica el total de la palabra. Varias bonificaciones de palabra se multiplican entre s\u00ED: dos dobles dan cuatro veces el total.",
              "Un comod\u00EDn en doble o triple letra sigue valiendo cero. En una casilla de palabra s\u00ED multiplica el valor de toda la palabra. Si despu\u00E9s alargas esa palabra, no vuelves a usar las bonificaciones ya ocupadas.",
              "Usar tus siete fichas en una sola jugada da 50 puntos adicionales. Se a\u00F1aden despu\u00E9s de puntuar las palabras y no se multiplican. S consulta los resultados."),
            rule_section(:exchange, "Cambiar fichas o pasar",
              "Puedes gastar el turno en cambiar fichas en vez de formar una palabra. Pulsa G, recorre las fichas con las flechas y marca las que entregas con Espacio. Enter confirma el cambio y Escape lo cancela.",
              "Puedes cambiar entre una y siete fichas si quedan al menos ocho en la bolsa. Las devueltas entran antes de sacar las nuevas, as\u00ED que podr\u00EDas recuperar alguna. E cuenta las fichas de la bolsa y de los atriles.",
              "P permite pasar sin jugar ni cambiar. Si ya hab\u00EDas preparado letras, antes de pasar o cambiar se pide confirmaci\u00F3n para retirarlas del tablero."),
            rule_section(:ending, "Final y recuento",
              "La partida termina de una de estas formas:",
              "- Con la bolsa vac\u00EDa, alguien usa todas sus fichas. Su jugada termina la partida.",
              "- Ya no es posible cambiar fichas y pasan tres rondas completas de turnos sin ninguna palabra jugada. La partida queda bloqueada. Una palabra interrumpe este recuento incluso si vale cero puntos.",
              "Cada jugador resta el valor de las fichas que conserve. Quien haya vaciado el atril recibe adem\u00E1s la suma de las fichas ajenas. Si la partida se bloque\u00F3, no hay esa bonificaci\u00F3n. Un comod\u00EDn sin usar vale cero.",
              "Despu\u00E9s del ajuste gana quien tenga m\u00E1s puntos. Si varios comparten el m\u00E1ximo, comparten la victoria."),
            rule_section(:language, "Idioma y diccionario",
              "Antes de jugar puedes elegir fichas y diccionario en polaco o ingl\u00E9s. Cambian las letras, sus cantidades y sus valores, aunque ambos juegos tienen cien fichas en total.",
              "La edici\u00F3n polaca usa el diccionario SJP incluido; la inglesa, Wordnik. Pueden diferir de los diccionarios de torneo. La aceptaci\u00F3n depende del diccionario del idioma elegido."),
            rule_section(:penalties, "Penalizaciones por palabras rechazadas",
              "Puedes elegir qu\u00E9 ocurre cuando presentas una palabra que no figura en el diccionario:",
              "- Permitir que corrijas la jugada, como en las reglas habituales.",
              "- Terminar el turno tras el rechazo. Juega la siguiente persona y tus fichas quedan en el atril.",
              "Ambas opciones admiten cero, 5 o 10 puntos de penalizaci\u00F3n. Una pulsaci\u00F3n de F solo puede producir una penalizaci\u00F3n, aunque haya varias palabras incorrectas. Los errores de colocaci\u00F3n, como un hueco, no reciben esta penalizaci\u00F3n."),
            rule_section(:time, "Tiempo por turno",
              "Por defecto no hay l\u00EDmite. Puedes activarlo antes de jugar. Abarca todo el turno, incluida la elecci\u00F3n de una letra para el comod\u00EDn y la correcci\u00F3n de palabras rechazadas.",
              "Al agotarse, las fichas preparadas regresan al atril y pasas el turno. Agotar el tiempo no a\u00F1ade por s\u00ED mismo una penalizaci\u00F3n de puntos."),
            rule_section(:personal, "Atril y anuncios de letras",
              "Si no tienes fichas preparadas, I cambia el orden del atril entre recepci\u00F3n, alfab\u00E9tico y vocales primero. Las teclas del 1 al 7 leen cada posici\u00F3n. Shift con una de esas cifras coloca directamente esa ficha en la casilla del cursor.",
              "Puedes seguir en el tablero las letras que otra persona est\u00E1 preparando antes de confirmar su palabra. Ctrl+P activa los anuncios al a\u00F1adirlas o retirarlas; vuelve a pulsarlo para desactivarlos."),
            rule_section(:controls, "Teclas de referencia",
              "Flechas: recorrer el tablero o una lista.",
              "Enter: elegir y colocar una ficha; confirmar las fichas marcadas para un cambio.",
              "Retroceso: retirar la ficha sin confirmar de la casilla actual.",
              "Z: retirar todas las fichas de la jugada preparada.",
              "F: presentar las palabras.",
              "Y: leer las palabras preparadas y sus puntos sin consultar el diccionario.",
              "Escape: cancelar la elecci\u00F3n de ficha o el cambio.",
              "C: leer el atril.",
              "I: cambiar el orden del atril si a\u00FAn no has preparado letras.",
              "G: elegir fichas para cambiar.",
              "Espacio en la lista de cambio: marcar o desmarcar una ficha.",
              "P: pasar.",
              "E: contar las fichas de los atriles y de la bolsa.",
              "L: revisar las palabras jugadas.",
              "S: consultar los resultados.",
              "T: consultar de qui\u00E9n es el turno.",
              "1: leer la primera ficha.",
              "2: leer la segunda ficha.",
              "3: leer la tercera ficha.",
              "4: leer la cuarta ficha.",
              "5: leer la quinta ficha.",
              "6: leer la sexta ficha.",
              "7: leer la s\u00E9ptima ficha.",
              "Shift+1: colocar la primera ficha en la casilla del cursor.",
              "Shift+2: colocar la segunda ficha en la casilla del cursor.",
              "Shift+3: colocar la tercera ficha en la casilla del cursor.",
              "Shift+4: colocar la cuarta ficha en la casilla del cursor.",
              "Shift+5: colocar la quinta ficha en la casilla del cursor.",
              "Shift+6: colocar la sexta ficha en la casilla del cursor.",
              "Shift+7: colocar la s\u00E9ptima ficha en la casilla del cursor.",
              "Ctrl+P: activar o desactivar anuncios de letras colocadas y retiradas.")
          ]
        when "pl"
          [
            rule_section(:goal, "Cel gry i plansza",
              "W Scrabble zdobywasz punkty, uk\u0142adaj\u0105c s\u0142owa z p\u0142ytek z literami. Wsp\u00F3lnie z pozosta\u0142ymi graczami rozbudowujesz jedn\u0105 krzy\u017C\u00F3wk\u0119, ale ka\u017Cdy zbiera punkty za w\u0142asne s\u0142owa. Wygrywa osoba, kt\u00F3ra na koniec gry ma najwi\u0119cej punkt\u00F3w.",
              "Gra jest przeznaczona dla dw\u00F3ch do czterech os\u00F3b. Ka\u017Cdy dostaje siedem p\u0142ytek na stojak. C odczytuje twoje litery razem z ich warto\u015Bciami. Po przyj\u0119tym ruchu dobierasz p\u0142ytki do siedmiu, dop\u00F3ki s\u0105 jeszcze w worku.",
              "Plansza ma pi\u0119tna\u015Bcie kolumn, od A do O, i pi\u0119tna\u015Bcie rz\u0119d\u00F3w, od 1 do 15. Poruszasz si\u0119 po niej strza\u0142kami. Us\u0142yszysz najpierw liter\u0119 albo informacj\u0119, \u017Ce pole jest puste, a potem jego wsp\u00F3\u0142rz\u0119dne. Niekt\u00F3re puste pola maj\u0105 te\u017C premi\u0119 zwi\u0119kszaj\u0105c\u0105 wynik ruchu."),
            rule_section(:placement, "Gdzie mo\u017Cna u\u0142o\u017Cy\u0107 s\u0142owo",
              "Pierwsze s\u0142owo musi przechodzi\u0107 przez \u015Brodkowe pole H8. Nast\u0119pne do\u0142\u0105czasz do tego, co ju\u017C le\u017Cy na planszy: mo\u017Cesz przed\u0142u\u017Cy\u0107 wyraz, skrzy\u017Cowa\u0107 z nim nowy albo u\u0142o\u017Cy\u0107 litery obok i utworzy\u0107 w ten spos\u00F3b kilka s\u0142\u00F3w.",
              "Przy ka\u017Cdym ruchu obowi\u0105zuj\u0105 te warunki:",
              "- Wszystkie dok\u0142adane w tej turze p\u0142ytki musz\u0105 le\u017Ce\u0107 w jednym rz\u0119dzie albo jednej kolumnie. S\u0142owa czyta si\u0119 od lewej do prawej lub z g\u00F3ry na d\u00F3\u0142.",
              "- Mi\u0119dzy literami gotowego s\u0142owa nie mo\u017Ce by\u0107 pustych p\u00F3l. Mo\u017Cesz za to wykorzysta\u0107 w \u015Brodku litery, kt\u00F3re le\u017Ca\u0142y tam wcze\u015Bniej.",
              "- Ka\u017Cde nowe s\u0142owo musi mie\u0107 co najmniej dwie litery i nale\u017Ce\u0107 do s\u0142ownika gry. Trzeba wi\u0119c sprawdzi\u0107 r\u00F3wnie\u017C kr\u00F3tsze s\u0142owa powsta\u0142e na skrzy\u017Cowaniach, nie tylko g\u0142\u00F3wny wyraz.",
              "Litery z przyj\u0119tych ruch\u00F3w pozostaj\u0105 na planszy. Nie przesuwasz ich i nie zabierasz, lecz mo\u017Cesz u\u017Cywa\u0107 ich w kolejnych s\u0142owach."),
            rule_section(:play, "Uk\u0142adanie i zatwierdzanie",
              "Przejd\u017A strza\u0142kami na puste pole, na kt\u00F3rym chcesz zacz\u0105\u0107 dok\u0142ada\u0107 litery, i naci\u015Bnij Enter. Otworzy si\u0119 lista dost\u0119pnych p\u0142ytek ze stojaka. Wybierz jedn\u0105 strza\u0142kami i zatwierd\u017A Enterem. P\u0142ytka pojawi si\u0119 na wybranym polu, ale tw\u00F3j ruch nie jest jeszcze zako\u0144czony.",
              "Tak samo po\u0142\u00F3\u017C pozosta\u0142e litery. Je\u015Bli si\u0119 pomylisz, wr\u00F3\u0107 na pole z do\u0142o\u017Con\u0105 p\u0142ytk\u0105 i naci\u015Bnij Backspace, \u017Ceby j\u0105 zdj\u0105\u0107. Z usuwa wszystkie p\u0142ytki do\u0142o\u017Cone w tej turze i pozwala zacz\u0105\u0107 uk\u0142adanie od nowa.",
              "Y odczytuje przygotowane s\u0142owa i ich przewidywan\u0105 punktacj\u0119. Nie sprawdza jeszcze, czy s\u0142ownik je uzna. Kiedy uk\u0142ad jest gotowy, zatwierd\u017A go klawiszem F. Dopiero wtedy s\u0142owa s\u0105 sprawdzane, p\u0142ytki zostaj\u0105 na planszy, dostajesz punkty i ko\u0144czysz tur\u0119.",
              "Je\u015Bli s\u0142ownik nie zna kt\u00F3rego\u015B wyrazu, us\u0142yszysz jego nazw\u0119, a przygotowane p\u0142ytki wr\u00F3c\u0105 na stojak. Przy zwyk\u0142ych zasadach mo\u017Cesz u\u0142o\u017Cy\u0107 co\u015B innego w tej samej turze i nie tracisz punkt\u00F3w. B\u0142\u0105d u\u0142o\u017Cenia, na przyk\u0142ad luka albo brak po\u0142\u0105czenia z krzy\u017C\u00F3wk\u0105, r\u00F3wnie\u017C wymaga poprawy."),
            rule_section(:blanks, "Blanki",
              "Blank jest p\u0142ytk\u0105 bez litery. Mo\u017Ce zast\u0105pi\u0107 dowoln\u0105 liter\u0119, wi\u0119c przy jego uk\u0142adaniu pojawi si\u0119 dodatkowy wyb\u00F3r. Wska\u017C liter\u0119 strza\u0142kami i potwierd\u017A Enterem. Dalej u\u017Cywasz blanku w s\u0142owie tak jak zwyk\u0142ej p\u0142ytki.",
              "Blank jest zawsze wart zero punkt\u00F3w. Po zatwierdzeniu ruchu zachowuje wybran\u0105 liter\u0119 do ko\u0144ca partii. W zestawie s\u0105 dwa blanki."),
            rule_section(:points, "Punktacja",
              "Dostajesz punkty za ka\u017Cde s\u0142owo utworzone w swoim ruchu. Sumujesz warto\u015Bci wszystkich jego liter, tak\u017Ce tych, kt\u00F3re le\u017Ca\u0142y na planszy wcze\u015Bniej. Je\u015Bli do\u0142o\u017Cona litera nale\u017Cy jednocze\u015Bnie do nowego s\u0142owa poziomego i pionowego, liczysz j\u0105 w obu.",
              "Premie pola dzia\u0142aj\u0105 tylko przy pierwszym po\u0142o\u017Ceniu na nim p\u0142ytki:",
              "- Premia literowa podwaja albo potraja warto\u015B\u0107 p\u0142ytki po\u0142o\u017Conej na tym polu. Nast\u0119pnie dodajesz do niej warto\u015Bci pozosta\u0142ych liter s\u0142owa.",
              "- Premia s\u0142owna podwaja albo potraja wynik ca\u0142ego wyrazu. Je\u015Bli jednym s\u0142owem zakryjesz kilka takich p\u00F3l, mno\u017Cniki si\u0119 \u0142\u0105cz\u0105: dwa podwojenia daj\u0105 czterokrotny wynik.",
              "Blank na polu z premi\u0105 literow\u0105 nadal jest wart zero. Je\u015Bli jednak po\u0142o\u017Cysz go na premii s\u0142ownej, podwoi lub potroi warto\u015B\u0107 ca\u0142ego wyrazu. Przy p\u00F3\u017Aniejszym przed\u0142u\u017Caniu s\u0142owa nie liczysz ponownie premii z zaj\u0119tych ju\u017C p\u00F3l.",
              "Za wy\u0142o\u017Cenie wszystkich siedmiu p\u0142ytek w jednym ruchu dostajesz dodatkowe 50 punkt\u00F3w. Ta premia dochodzi po policzeniu s\u0142\u00F3w i nie jest ju\u017C mno\u017Cona. S pozwala sprawdzi\u0107 wyniki."),
            rule_section(:exchange, "Wymiana p\u0142ytek i pas",
              "Je\u017Celi nie chcesz uk\u0142ada\u0107 s\u0142owa, mo\u017Cesz po\u015Bwi\u0119ci\u0107 tur\u0119 na wymian\u0119 p\u0142ytek. Naci\u015Bnij G, wybierz na li\u015Bcie niepotrzebne p\u0142ytki strza\u0142kami i zaznaczaj je Spacj\u0105. Enter zatwierdza wymian\u0119, a Escape z niej rezygnuje.",
              "Wymieni\u0107 mo\u017Cna od jednej do siedmiu p\u0142ytek, o ile w worku zosta\u0142o przynajmniej osiem. Oddane p\u0142ytki wracaj\u0105 do worka przed dobraniem, wi\u0119c kt\u00F3ra\u015B mo\u017Ce do ciebie wr\u00F3ci\u0107. Liczb\u0119 p\u0142ytek w worku i na stojakach sprawdzisz przez E.",
              "Klawiszem P mo\u017Cesz spasowa\u0107, czyli zako\u0144czy\u0107 tur\u0119 bez uk\u0142adania s\u0142owa i bez wymiany p\u0142ytek. Je\u015Bli zacz\u0105\u0142e\u015B ju\u017C uk\u0142ada\u0107 s\u0142owo, przed pasem lub wymian\u0105 gra poprosi o zgod\u0119 na zdj\u0119cie tych liter z planszy."),
            rule_section(:ending, "Koniec i rozliczenie partii",
              "Partia mo\u017Ce zako\u0144czy\u0107 si\u0119 na dwa sposoby:",
              "- Worek jest pusty, a kto\u015B wykorzystuje wszystkie swoje p\u0142ytki. Po jego ruchu gra si\u0119 ko\u0144czy.",
              "- Wymiana jest ju\u017C niemo\u017Cliwa, a przez trzy pe\u0142ne kolejki nikt nie zagra s\u0142owa. Gra zostaje wtedy zablokowana. Zagranie s\u0142owa przerywa to odliczanie, nawet je\u015Bli jest warte zero punkt\u00F3w.",
              "Na koniec ka\u017Cdemu odejmuje si\u0119 warto\u015B\u0107 p\u0142ytek pozosta\u0142ych na stojaku. Gracz, kt\u00F3ry opr\u00F3\u017Cni\u0142 sw\u00F3j stojak, dostaje dodatkowo sum\u0119 warto\u015Bci p\u0142ytek pozosta\u0142ych os\u00F3b. Przy zablokowaniu nie ma tej dodatkowej nagrody. Blank pozosta\u0142y w r\u0119ce liczy si\u0119 za zero.",
              "Po tych zmianach por\u00F3wnujecie wyniki. Wygrywa osoba z najwy\u017Cszym wynikiem, a r\u00F3wne najwy\u017Csze wyniki daj\u0105 wsp\u00F3lne zwyci\u0119stwo."),
            rule_section(:language, "J\u0119zyk p\u0142ytek i s\u0142ownik",
              "Przed gr\u0105 w ustawieniach sto\u0142u mo\u017Cesz wybra\u0107 polskie albo angielskie p\u0142ytki i s\u0142ownik. Zmienia si\u0119 zestaw liter, ich liczba i warto\u015Bci. W obu j\u0119zykach jest \u0142\u0105cznie sto p\u0142ytek.",
              "Polska gra korzysta z do\u0142\u0105czonego s\u0142ownika SJP, a angielska z Wordnik. Mog\u0105 one r\u00F3\u017Cni\u0107 si\u0119 od s\u0142ownik\u00F3w u\u017Cywanych na turniejach. O przyj\u0119ciu s\u0142owa decyduje s\u0142ownik wybranego j\u0119zyka."),
            rule_section(:penalties, "Kary za niepoprawne s\u0142owo",
              "W ustawieniach sto\u0142u mo\u017Cna zmieni\u0107 to, co nast\u0105pi po zg\u0142oszeniu s\u0142owa nieznanego s\u0142ownikowi:",
              "- Mo\u017Cna pozostawi\u0107 mo\u017Cliwo\u015B\u0107 poprawienia ruchu. Tak jest w grze podstawowej.",
              "- Mo\u017Cna zamiast tego zako\u0144czy\u0107 tur\u0119 po odrzuceniu s\u0142owa. Nast\u0119pna osoba zagra, a twoje p\u0142ytki pozostan\u0105 na stojaku.",
              "Ka\u017Cda z tych zasad jest dost\u0119pna bez kary punktowej albo z odj\u0119ciem 5 lub 10 punkt\u00F3w. Za jedno naci\u015Bni\u0119cie F nalicza si\u0119 najwy\u017Cej jedn\u0105 kar\u0119, nawet je\u015Bli b\u0142\u0119dnych s\u0142\u00F3w jest kilka. B\u0142\u0119dy u\u0142o\u017Cenia, takie jak pozostawiona luka, nie podlegaj\u0105 tej karze."),
            rule_section(:time, "Czas na ruch",
              "Zwykle nie ma limitu czasu na ruch. Mo\u017Cna go w\u0142\u0105czy\u0107 w ustawieniach sto\u0142u przed gr\u0105. Limit obejmuje ca\u0142\u0105 tur\u0119, \u0142\u0105cznie z wybieraniem litery blanku i ewentualnym poprawianiem odrzuconego s\u0142owa.",
              "Po jego up\u0142ywie przygotowane p\u0142ytki wracaj\u0105 na stojak, a tura ko\u0144czy si\u0119 pasem. Nie dostajesz za sam up\u0142yw czasu dodatkowej kary punktowej."),
            rule_section(:personal, "Stojak i odczyt uk\u0142adanych liter",
              "Gdy nie masz \u017Cadnych przygotowanych p\u0142ytek, klawisz I zmienia kolejno\u015B\u0107 liter na stojaku. Mo\u017Cesz przegl\u0105da\u0107 je w kolejno\u015Bci otrzymania, alfabetycznie albo z samog\u0142oskami na pocz\u0105tku. Klawisze od 1 do 7 odczytuj\u0105 kolejne pozycje. Shift z dan\u0105 cyfr\u0105 od razu k\u0142adzie t\u0119 p\u0142ytk\u0119 na polu pod kursorem.",
              "Na planszy mo\u017Cesz \u015Bledzi\u0107 litery uk\u0142adane przez drug\u0105 osob\u0119 jeszcze przed zatwierdzeniem jej s\u0142owa. Je\u015Bli chcesz s\u0142ysze\u0107 komunikaty o dok\u0142adaniu i zdejmowaniu tych liter, w\u0142\u0105cz je przez Ctrl+P. Ponowne u\u017Cycie skr\u00F3tu je wy\u0142\u0105cza."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: poruszaj si\u0119 po planszy lub otwartej li\u015Bcie.",
              "Enter: wybierz p\u0142ytk\u0119 i po\u0142\u00F3\u017C j\u0105; w oknie wymiany zatwierd\u017A zaznaczone p\u0142ytki.",
              "Backspace: zdejmij niezatwierdzon\u0105 p\u0142ytk\u0119 z pola pod kursorem.",
              "Z: usu\u0144 wszystkie p\u0142ytki przygotowanego ruchu.",
              "F: zatwierd\u017A u\u0142o\u017Cone s\u0142owa.",
              "Y: odczytaj przygotowane s\u0142owa i punkty, bez sprawdzania s\u0142ownika.",
              "Escape: anuluj wyb\u00F3r p\u0142ytki lub wymian\u0119.",
              "C: odczytaj stojak.",
              "I: zmie\u0144 kolejno\u015B\u0107 p\u0142ytek, gdy niczego jeszcze nie uk\u0142adasz.",
              "G: wybierz p\u0142ytki do wymiany.",
              "Spacja na li\u015Bcie wymiany: zaznacz lub odznacz p\u0142ytk\u0119.",
              "P: spasuj.",
              "E: odczytaj liczb\u0119 p\u0142ytek na stojakach i w worku.",
              "L: przegl\u0105daj zagrane s\u0142owa.",
              "S: odczytaj wyniki.",
              "T: sprawd\u017A, czyja jest tura.",
              "1: odczytaj pierwsz\u0105 p\u0142ytk\u0119 stojaka.",
              "2: odczytaj drug\u0105 p\u0142ytk\u0119 stojaka.",
              "3: odczytaj trzeci\u0105 p\u0142ytk\u0119 stojaka.",
              "4: odczytaj czwart\u0105 p\u0142ytk\u0119 stojaka.",
              "5: odczytaj pi\u0105t\u0105 p\u0142ytk\u0119 stojaka.",
              "6: odczytaj sz\u00F3st\u0105 p\u0142ytk\u0119 stojaka.",
              "7: odczytaj si\u00F3dm\u0105 p\u0142ytk\u0119 stojaka.",
              "Shift+1: po\u0142\u00F3\u017C pierwsz\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Shift+2: po\u0142\u00F3\u017C drug\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Shift+3: po\u0142\u00F3\u017C trzeci\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Shift+4: po\u0142\u00F3\u017C czwart\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Shift+5: po\u0142\u00F3\u017C pi\u0105t\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Shift+6: po\u0142\u00F3\u017C sz\u00F3st\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Shift+7: po\u0142\u00F3\u017C si\u00F3dm\u0105 p\u0142ytk\u0119 na polu pod kursorem.",
              "Ctrl+P: prze\u0142\u0105cz komunikaty o uk\u0142adaniu i zdejmowaniu liter.")
          ]
        when "ru"
          [
            rule_section(:goal, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B \u0438 \u043F\u043E\u043B\u0435",
              "\u0412 \u0441\u043A\u0440\u044D\u0431\u0431\u043B\u0435 \u043E\u0442 \u0434\u0432\u0443\u0445 \u0434\u043E \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u0441\u043B\u043E\u0432\u0430 \u0438\u0437 \u0444\u0438\u0448\u0435\u043A \u0441 \u0431\u0443\u043A\u0432\u0430\u043C\u0438. \u0412\u044B \u0432\u043C\u0435\u0441\u0442\u0435 \u0441\u0442\u0440\u043E\u0438\u0442\u0435 \u043E\u0434\u0438\u043D \u043A\u0440\u043E\u0441\u0441\u0432\u043E\u0440\u0434, \u043D\u043E \u043E\u0447\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u0437\u0430 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0438\u0442\u043E\u0433\u043E\u0432\u044B\u0439 \u0441\u0447\u0451\u0442.",
              "\u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043D\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0435 \u0441\u0435\u043C\u044C \u0444\u0438\u0448\u0435\u043A. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u0430\u0448\u0438 \u0431\u0443\u043A\u0432\u044B \u0438 \u0438\u0445 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C. \u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u043D\u044F\u0442\u043E\u0433\u043E \u0445\u043E\u0434\u0430 \u0432\u044B \u0434\u043E\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0434\u043E \u0441\u0435\u043C\u0438, \u043F\u043E\u043A\u0430 \u0432 \u043C\u0435\u0448\u043A\u0435 \u0435\u0449\u0451 \u0435\u0441\u0442\u044C \u0444\u0438\u0448\u043A\u0438.",
              "\u041D\u0430 \u043F\u043E\u043B\u0435 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0442\u043E\u043B\u0431\u0446\u043E\u0432, A\u2013O, \u0438 \u043F\u044F\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0440\u044F\u0434\u043E\u0432, 1\u201315. \u041F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0439\u0442\u0435\u0441\u044C \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0432\u0443\u0447\u0438\u0442 \u0431\u0443\u043A\u0432\u0430 \u0438\u043B\u0438 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u0435 \u043E \u043F\u0443\u0441\u0442\u043E\u0439 \u043A\u043B\u0435\u0442\u043A\u0435, \u0437\u0430\u0442\u0435\u043C \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u044B. \u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043F\u0443\u0441\u0442\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438 \u0434\u0430\u044E\u0442 \u043F\u0440\u0435\u043C\u0438\u044E \u043A \u043E\u0447\u043A\u0430\u043C."),
            rule_section(:placement, "\u0413\u0434\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0442\u044C \u0441\u043B\u043E\u0432\u0430",
              "\u041F\u0435\u0440\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u0434\u043E\u043B\u0436\u043D\u043E \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442\u044C \u0447\u0435\u0440\u0435\u0437 \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 H8. \u041A\u0430\u0436\u0434\u043E\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u044F\u0435\u0442\u0441\u044F \u0441 \u0443\u0436\u0435 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u043C: \u043C\u043E\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u043B\u0438\u0442\u044C \u0441\u043B\u043E\u0432\u043E, \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u044C \u0435\u0433\u043E \u043D\u043E\u0432\u044B\u043C \u0438\u043B\u0438 \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0431\u0443\u043A\u0432\u044B \u0440\u044F\u0434\u043E\u043C, \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u0432 \u0441\u0440\u0430\u0437\u0443 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u043B\u043E\u0432.",
              "\u041F\u0440\u0438 \u043A\u0430\u0436\u0434\u043E\u043C \u0445\u043E\u0434\u0435 \u0441\u043E\u0431\u043B\u044E\u0434\u0430\u0439\u0442\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u044F:",
              "- \u0412\u0441\u0435 \u043D\u043E\u0432\u044B\u0435 \u0444\u0438\u0448\u043A\u0438 \u043A\u043B\u0430\u0434\u0443\u0442\u0441\u044F \u0432 \u043E\u0434\u0438\u043D \u0440\u044F\u0434 \u0438\u043B\u0438 \u043E\u0434\u0438\u043D \u0441\u0442\u043E\u043B\u0431\u0435\u0446. \u0421\u043B\u043E\u0432\u0430 \u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0441\u043B\u0435\u0432\u0430 \u043D\u0430\u043F\u0440\u0430\u0432\u043E \u043B\u0438\u0431\u043E \u0441\u0432\u0435\u0440\u0445\u0443 \u0432\u043D\u0438\u0437.",
              "- \u0412 \u0433\u043E\u0442\u043E\u0432\u043E\u043C \u0441\u043B\u043E\u0432\u0435 \u043D\u0435 \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u043F\u0440\u043E\u0431\u0435\u043B\u043E\u0432. \u041C\u0435\u0436\u0434\u0443 \u043D\u043E\u0432\u044B\u043C\u0438 \u0431\u0443\u043A\u0432\u0430\u043C\u0438 \u043C\u043E\u0433\u0443\u0442 \u0441\u0442\u043E\u044F\u0442\u044C \u0440\u0430\u043D\u0435\u0435 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435.",
              "- \u041A\u0430\u0436\u0434\u043E\u0435 \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u0434\u043E\u043B\u0436\u043D\u043E \u0441\u043E\u0441\u0442\u043E\u044F\u0442\u044C \u0445\u043E\u0442\u044F \u0431\u044B \u0438\u0437 \u0434\u0432\u0443\u0445 \u0431\u0443\u043A\u0432 \u0438 \u0431\u044B\u0442\u044C \u0432 \u0438\u0433\u0440\u043E\u0432\u043E\u043C \u0441\u043B\u043E\u0432\u0430\u0440\u0435. \u042D\u0442\u043E \u043A\u0430\u0441\u0430\u0435\u0442\u0441\u044F \u0438 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0445 \u043F\u043E\u043F\u0435\u0440\u0435\u0447\u043D\u044B\u0445 \u0441\u043B\u043E\u0432, \u0430 \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0433\u043E.",
              "\u041F\u0440\u0438\u043D\u044F\u0442\u044B\u0435 \u0431\u0443\u043A\u0432\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u0441\u0432\u043E\u0438\u0445 \u043C\u0435\u0441\u0442\u0430\u0445 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u043F\u0430\u0440\u0442\u0438\u0438. \u041F\u0435\u0440\u0435\u0434\u0432\u0438\u0433\u0430\u0442\u044C \u0438 \u0437\u0430\u0431\u0438\u0440\u0430\u0442\u044C \u0438\u0445 \u043D\u0435\u043B\u044C\u0437\u044F, \u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0432 \u043D\u043E\u0432\u044B\u0445 \u0441\u043B\u043E\u0432\u0430\u0445 \u043C\u043E\u0436\u043D\u043E."),
            rule_section(:play, "\u0412\u044B\u043A\u043B\u0430\u0434\u043A\u0430 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u0435 \u0445\u043E\u0434\u0430",
              "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0441\u043F\u0438\u0441\u043E\u043A \u0432\u0430\u0448\u0438\u0445 \u0444\u0438\u0448\u0435\u043A. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0431\u0443\u043A\u0432\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u041E\u043D\u0430 \u043E\u043A\u0430\u0436\u0435\u0442\u0441\u044F \u043D\u0430 \u043F\u043E\u043B\u0435, \u043D\u043E \u0445\u043E\u0434 \u043F\u043E\u043A\u0430 \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D.",
              "\u0422\u0430\u043A\u0438\u043C \u0436\u0435 \u0441\u043F\u043E\u0441\u043E\u0431\u043E\u043C \u0432\u044B\u043B\u043E\u0436\u0438\u0442\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0431\u0443\u043A\u0432\u044B. \u0414\u043B\u044F \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u0432\u0435\u0440\u043D\u0438\u0442\u0435\u0441\u044C \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0443 \u0441 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u043E \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u043E\u0439 \u0444\u0438\u0448\u043A\u043E\u0439 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Backspace. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 Z \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0441\u0435 \u0444\u0438\u0448\u043A\u0438 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0445\u043E\u0434\u0430, \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044F \u043D\u0430\u0447\u0430\u0442\u044C \u0437\u0430\u043D\u043E\u0432\u043E.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 Y \u0447\u0438\u0442\u0430\u0435\u0442 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u0438 \u043F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043E\u0447\u043A\u0438, \u0435\u0449\u0451 \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044F \u0441\u043B\u043E\u0432\u0430\u0440\u044C. \u041A\u043E\u0433\u0434\u0430 \u0432\u0441\u0451 \u0433\u043E\u0442\u043E\u0432\u043E, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 F. \u0422\u043E\u043B\u044C\u043A\u043E \u0442\u0435\u043F\u0435\u0440\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u044E\u0442\u0441\u044F \u0441\u043B\u043E\u0432\u0430, \u0437\u0430\u043A\u0440\u0435\u043F\u043B\u044F\u044E\u0442\u0441\u044F \u0444\u0438\u0448\u043A\u0438, \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u0447\u043A\u0438 \u0438 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0445\u043E\u0434.",
              "\u0415\u0441\u043B\u0438 \u043A\u0430\u043A\u043E\u0433\u043E-\u0442\u043E \u0441\u043B\u043E\u0432\u0430 \u043D\u0435\u0442 \u0432 \u0441\u043B\u043E\u0432\u0430\u0440\u0435, \u0438\u0433\u0440\u0430 \u043D\u0430\u0437\u043E\u0432\u0451\u0442 \u0435\u0433\u043E, \u0430 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0444\u0438\u0448\u043A\u0438 \u0432\u0435\u0440\u043D\u0443\u0442\u0441\u044F \u043D\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0443. \u0412 \u043E\u0431\u044B\u0447\u043D\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u0432 \u0442\u043E\u0442 \u0436\u0435 \u0445\u043E\u0434 \u0431\u0435\u0437 \u043F\u043E\u0442\u0435\u0440\u0438 \u043E\u0447\u043A\u043E\u0432. \u041E\u0448\u0438\u0431\u043A\u0443 \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u2014 \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0440\u0430\u0437\u0440\u044B\u0432 \u0438\u043B\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0441\u0432\u044F\u0437\u0438 \u0441 \u043A\u0440\u043E\u0441\u0441\u0432\u043E\u0440\u0434\u043E\u043C \u2014 \u0442\u043E\u0436\u0435 \u043D\u0443\u0436\u043D\u043E \u0438\u0441\u043F\u0440\u0430\u0432\u0438\u0442\u044C."),
            rule_section(:blanks, "\u041F\u0443\u0441\u0442\u044B\u0435 \u0444\u0438\u0448\u043A\u0438",
              "\u041F\u0443\u0441\u0442\u0430\u044F \u0444\u0438\u0448\u043A\u0430 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043B\u044E\u0431\u0443\u044E \u0431\u0443\u043A\u0432\u0443. \u041F\u0440\u0438 \u0435\u0451 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u0435 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u043F\u0438\u0441\u043E\u043A: \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0431\u0443\u043A\u0432\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter. \u0414\u0430\u043B\u044C\u0448\u0435 \u043E\u043D\u0430 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u0441\u043B\u043E\u0432\u0435 \u043A\u0430\u043A \u043E\u0431\u044B\u0447\u043D\u0430\u044F \u0431\u0443\u043A\u0432\u0430.",
              "\u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043F\u0443\u0441\u0442\u043E\u0439 \u0444\u0438\u0448\u043A\u0438 \u0432\u0441\u0435\u0433\u0434\u0430 \u043D\u0443\u043B\u0435\u0432\u0430\u044F. \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \u0445\u043E\u0434\u0430 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u0443\u044E \u0434\u043B\u044F \u043D\u0435\u0451 \u0431\u0443\u043A\u0432\u0443 \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043D\u0435\u043B\u044C\u0437\u044F. \u0412 \u043D\u0430\u0431\u043E\u0440\u0435 \u0434\u0432\u0435 \u0442\u0430\u043A\u0438\u0435 \u0444\u0438\u0448\u043A\u0438."),
            rule_section(:points, "\u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u043E\u0447\u043A\u043E\u0432",
              "\u0412\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u043E\u0447\u043A\u0438 \u0437\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u043D\u043E\u0435 \u044D\u0442\u0438\u043C \u0445\u043E\u0434\u043E\u043C. \u0421\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0432\u0441\u0435\u0445 \u0435\u0433\u043E \u0431\u0443\u043A\u0432, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0443\u0436\u0435 \u043B\u0435\u0436\u0430\u0432\u0448\u0438\u0435 \u043D\u0430 \u043F\u043E\u043B\u0435. \u0415\u0441\u043B\u0438 \u043D\u043E\u0432\u0430\u044F \u0431\u0443\u043A\u0432\u0430 \u0432\u0445\u043E\u0434\u0438\u0442 \u0438 \u0432 \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u044C\u043D\u043E\u0435, \u0438 \u0432 \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u044C\u043D\u043E\u0435 \u043D\u043E\u0432\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u043E\u043D\u0430 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0432 \u043E\u0431\u043E\u0438\u0445.",
              "\u041F\u0440\u0435\u043C\u0438\u044F \u043A\u043B\u0435\u0442\u043A\u0438 \u0441\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u043B\u0438\u0448\u044C \u043F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u043C \u0440\u0430\u0437\u043C\u0435\u0449\u0435\u043D\u0438\u0438 \u043D\u0430 \u043D\u0435\u0439 \u0444\u0438\u0448\u043A\u0438:",
              "- \u041F\u0440\u0435\u043C\u0438\u044F \u0437\u0430 \u0431\u0443\u043A\u0432\u0443 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442 \u0438\u043B\u0438 \u0443\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043D\u043E\u0432\u043E\u0439 \u0444\u0438\u0448\u043A\u0438. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043A \u043D\u0435\u0439 \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0431\u0443\u043A\u0432 \u0441\u043B\u043E\u0432\u0430.",
              "- \u041F\u0440\u0435\u043C\u0438\u044F \u0437\u0430 \u0441\u043B\u043E\u0432\u043E \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442 \u0438\u043B\u0438 \u0443\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442 \u0441\u0443\u043C\u043C\u0443 \u0432\u0441\u0435\u0433\u043E \u0441\u043B\u043E\u0432\u0430. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0442\u0430\u043A\u0438\u0445 \u043F\u0440\u0435\u043C\u0438\u0439 \u043F\u0435\u0440\u0435\u043C\u043D\u043E\u0436\u0430\u044E\u0442\u0441\u044F: \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0434\u0432\u0430 \u0443\u0434\u0432\u043E\u0435\u043D\u0438\u044F \u0434\u0430\u044E\u0442 \u0447\u0435\u0442\u044B\u0440\u0451\u0445\u043A\u0440\u0430\u0442\u043D\u0443\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C.",
              "\u041F\u0443\u0441\u0442\u0430\u044F \u0444\u0438\u0448\u043A\u0430 \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0435 \u0441 \u043F\u0440\u0435\u043C\u0438\u0435\u0439 \u0437\u0430 \u0431\u0443\u043A\u0432\u0443 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0441\u0442\u043E\u0438\u0442 \u043D\u043E\u043B\u044C. \u041F\u0440\u0435\u043C\u0438\u044E \u0437\u0430 \u0441\u043B\u043E\u0432\u043E \u043E\u043D\u0430 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442, \u043A\u0430\u043A \u043B\u044E\u0431\u0430\u044F \u0434\u0440\u0443\u0433\u0430\u044F: \u0441\u0443\u043C\u043C\u0430 \u0441\u043B\u043E\u0432\u0430 \u0443\u0434\u0432\u043E\u0438\u0442\u0441\u044F \u0438\u043B\u0438 \u0443\u0442\u0440\u043E\u0438\u0442\u0441\u044F. \u041F\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u043F\u0440\u043E\u0434\u043B\u0435\u043D\u0438\u0438 \u0441\u043B\u043E\u0432\u0430 \u043F\u0440\u0435\u043C\u0438\u0438 \u0443\u0436\u0435 \u0437\u0430\u043D\u044F\u0442\u044B\u0445 \u043A\u043B\u0435\u0442\u043E\u043A \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u043D\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044E\u0442.",
              "\u0412\u044B\u043B\u043E\u0436\u0438\u0432 \u0437\u0430 \u043E\u0434\u0438\u043D \u0445\u043E\u0434 \u0432\u0441\u0435 \u0441\u0435\u043C\u044C \u0444\u0438\u0448\u0435\u043A, \u0432\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442\u0435 \u0435\u0449\u0451 50 \u043E\u0447\u043A\u043E\u0432. \u042D\u0442\u0430 \u043F\u0440\u0435\u043C\u0438\u044F \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430 \u0441\u043B\u043E\u0432 \u0438 \u043D\u0435 \u0443\u043C\u043D\u043E\u0436\u0430\u0435\u0442\u0441\u044F. \u0421\u0447\u0451\u0442 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 S."),
            rule_section(:exchange, "\u041E\u0431\u043C\u0435\u043D \u0438 \u043F\u0430\u0441",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u0441\u043B\u043E\u0432\u0430 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u0442\u0440\u0430\u0442\u0438\u0442\u044C \u0445\u043E\u0434 \u043D\u0430 \u043E\u0431\u043C\u0435\u043D \u0444\u0438\u0448\u0435\u043A. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 G, \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438\u0442\u0435 \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 \u043D\u0435\u043D\u0443\u0436\u043D\u044B\u0435 \u041F\u0440\u043E\u0431\u0435\u043B\u043E\u043C. Enter \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u043E\u0431\u043C\u0435\u043D, Escape \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0435\u0433\u043E.",
              "\u041C\u0435\u043D\u044F\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u043E\u0442 \u043E\u0434\u043D\u043E\u0439 \u0434\u043E \u0441\u0435\u043C\u0438 \u0444\u0438\u0448\u0435\u043A, \u0435\u0441\u043B\u0438 \u0432 \u043C\u0435\u0448\u043A\u0435 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u0445\u043E\u0442\u044F \u0431\u044B \u0432\u043E\u0441\u0435\u043C\u044C. \u041E\u0442\u0434\u0430\u0432\u0430\u0435\u043C\u044B\u0435 \u0444\u0438\u0448\u043A\u0438 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u0432 \u043C\u0435\u0448\u043E\u043A, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u0434\u043D\u0430 \u0438\u0437 \u043D\u0438\u0445 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u043F\u0430\u0441\u0442\u044C \u043A \u0432\u0430\u043C \u0441\u043D\u043E\u0432\u0430. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 E \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043C\u0435\u0448\u043A\u0430 \u0438 \u0440\u0430\u0437\u043C\u0435\u0440\u044B \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043E\u043A.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 P \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043F\u0430\u0441 \u2014 \u043A\u043E\u043D\u0435\u0446 \u0445\u043E\u0434\u0430 \u0431\u0435\u0437 \u0441\u043B\u043E\u0432\u0430 \u0438 \u0431\u0435\u0437 \u043E\u0431\u043C\u0435\u043D\u0430. \u0415\u0441\u043B\u0438 \u0432\u044B \u0443\u0436\u0435 \u043D\u0430\u0447\u0430\u043B\u0438 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u0443, \u043F\u0435\u0440\u0435\u0434 \u043F\u0430\u0441\u043E\u043C \u0438\u043B\u0438 \u043E\u0431\u043C\u0435\u043D\u043E\u043C \u0438\u0433\u0440\u0430 \u043F\u043E\u043F\u0440\u043E\u0441\u0438\u0442 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u044D\u0442\u0438\u0445 \u0431\u0443\u043A\u0432 \u043D\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0443."),
            rule_section(:ending, "\u041A\u043E\u043D\u0435\u0446 \u043F\u0430\u0440\u0442\u0438\u0438",
              "\u041F\u0430\u0440\u0442\u0438\u044F \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u0438\u043C \u0438\u0437 \u0434\u0432\u0443\u0445 \u0441\u043F\u043E\u0441\u043E\u0431\u043E\u0432:",
              "- \u041C\u0435\u0448\u043E\u043A \u043F\u0443\u0441\u0442, \u0438 \u0438\u0433\u0440\u043E\u043A \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043B \u0432\u0441\u0435 \u0441\u0432\u043E\u0438 \u0444\u0438\u0448\u043A\u0438. \u0415\u0433\u043E \u0445\u043E\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442 \u0438\u0433\u0440\u0443.",
              "- \u041E\u0431\u043C\u0435\u043D \u0443\u0436\u0435 \u043D\u0435\u0432\u043E\u0437\u043C\u043E\u0436\u0435\u043D, \u0438 \u0437\u0430 \u0442\u0440\u0438 \u043F\u043E\u043B\u043D\u044B\u0445 \u043A\u0440\u0443\u0433\u0430 \u043D\u0438\u043A\u0442\u043E \u043D\u0435 \u0441\u044B\u0433\u0440\u0430\u043B \u0441\u043B\u043E\u0432\u043E. \u042D\u0442\u043E \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u043A\u0430. \u041B\u044E\u0431\u043E\u0435 \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E, \u0434\u0430\u0436\u0435 \u043D\u0430 \u043D\u043E\u043B\u044C \u043E\u0447\u043A\u043E\u0432, \u043F\u0440\u0435\u0440\u044B\u0432\u0430\u0435\u0442 \u043E\u0442\u0441\u0447\u0451\u0442.",
              "\u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u044B\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u0444\u0438\u0448\u0435\u043A. \u0422\u043E\u0442, \u043A\u0442\u043E \u043E\u043F\u0443\u0441\u0442\u043E\u0448\u0438\u043B \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0443, \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0431\u0449\u0443\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043E\u0441\u0442\u0430\u0442\u043A\u043E\u0432 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432. \u041F\u0440\u0438 \u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u043A\u0435 \u044D\u0442\u043E\u0439 \u043D\u0430\u0433\u0440\u0430\u0434\u044B \u043D\u0435\u0442. \u041E\u0441\u0442\u0430\u0432\u0448\u0430\u044F\u0441\u044F \u043F\u0443\u0441\u0442\u0430\u044F \u0444\u0438\u0448\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0441\u0442\u043E\u0438\u0442.",
              "\u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u0438\u0445 \u043F\u043E\u043F\u0440\u0430\u0432\u043E\u043A \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0441\u0447\u0451\u0442. \u041F\u0440\u0438 \u0440\u0430\u0432\u0435\u043D\u0441\u0442\u0432\u0435 \u043B\u0443\u0447\u0448\u0438\u0445 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u043E\u0432 \u043F\u043E\u0431\u0435\u0434\u0430 \u043E\u0431\u0449\u0430\u044F."),
            rule_section(:language, "\u042F\u0437\u044B\u043A \u0431\u0443\u043A\u0432 \u0438 \u0441\u043B\u043E\u0432\u0430\u0440\u044C",
              "\u041F\u0435\u0440\u0435\u0434 \u0438\u0433\u0440\u043E\u0439 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u043B\u044C\u0441\u043A\u0438\u0435 \u0438\u043B\u0438 \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u0438\u0435 \u0431\u0443\u043A\u0432\u044B \u0438 \u0441\u043B\u043E\u0432\u0430\u0440\u044C. \u041E\u0442 \u044F\u0437\u044B\u043A\u0430 \u0437\u0430\u0432\u0438\u0441\u044F\u0442 \u0441\u043E\u0441\u0442\u0430\u0432 \u0431\u0443\u043A\u0432, \u0438\u0445 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0438 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C. \u0412 \u043E\u0431\u043E\u0438\u0445 \u043D\u0430\u0431\u043E\u0440\u0430\u0445 \u0432\u0441\u0435\u0433\u043E \u0441\u0442\u043E \u0444\u0438\u0448\u0435\u043A.",
              "\u0414\u043B\u044F \u043F\u043E\u043B\u044C\u0441\u043A\u043E\u0433\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043F\u0440\u0438\u043B\u0430\u0433\u0430\u0435\u043C\u044B\u0439 \u0441\u043B\u043E\u0432\u0430\u0440\u044C SJP, \u0434\u043B\u044F \u0430\u043D\u0433\u043B\u0438\u0439\u0441\u043A\u043E\u0433\u043E \u2014 Wordnik. \u041E\u043D\u0438 \u043C\u043E\u0433\u0443\u0442 \u043E\u0442\u043B\u0438\u0447\u0430\u0442\u044C\u0441\u044F \u043E\u0442 \u0442\u0443\u0440\u043D\u0438\u0440\u043D\u044B\u0445 \u0441\u043B\u043E\u0432\u0430\u0440\u0435\u0439. \u0414\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0441\u0442\u044C \u0441\u043B\u043E\u0432\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043B\u043E\u0432\u0430\u0440\u0451\u043C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u044F\u0437\u044B\u043A\u0430."),
            rule_section(:penalties, "\u0428\u0442\u0440\u0430\u0444 \u0437\u0430 \u043D\u0435\u043F\u0440\u0438\u043D\u044F\u0442\u043E\u0435 \u0441\u043B\u043E\u0432\u043E",
              "\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C, \u0447\u0442\u043E \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442 \u043F\u0440\u0438 \u0441\u043B\u043E\u0432\u0435, \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u043D\u0435\u0442 \u0432 \u0441\u043B\u043E\u0432\u0430\u0440\u0435:",
              "- \u0418\u0433\u0440\u043E\u043A \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u044F\u0435\u0442 \u0445\u043E\u0434 \u0438 \u043F\u0440\u043E\u0431\u0443\u0435\u0442 \u0441\u043D\u043E\u0432\u0430, \u043A\u0430\u043A \u0432 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0435.",
              "- \u0425\u043E\u0434 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F. \u0412\u0441\u0435 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0444\u0438\u0448\u043A\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0443, \u0430 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u0434\u0430\u043B\u044C\u0448\u0435.",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D \u0431\u0435\u0437 \u0448\u0442\u0440\u0430\u0444\u0430 \u043B\u0438\u0431\u043E \u0441\u043E \u0441\u043D\u044F\u0442\u0438\u0435\u043C 5 \u0438\u043B\u0438 10 \u043E\u0447\u043A\u043E\u0432. \u0417\u0430 \u043E\u0434\u043D\u043E \u043D\u0430\u0436\u0430\u0442\u0438\u0435 F \u043D\u0430\u0437\u043D\u0430\u0447\u0430\u0435\u0442\u0441\u044F \u043D\u0435 \u0431\u043E\u043B\u044C\u0448\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0448\u0442\u0440\u0430\u0444\u0430, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u043D\u0435\u0432\u0435\u0440\u043D\u044B\u0445 \u0441\u043B\u043E\u0432 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E. \u041E\u0448\u0438\u0431\u043A\u0438 \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u0430\u044F \u043A\u043B\u0435\u0442\u043A\u0430, \u0442\u0430\u043A\u0438\u043C \u0448\u0442\u0440\u0430\u0444\u043E\u043C \u043D\u0435 \u043D\u0430\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F."),
            rule_section(:time, "\u0412\u0440\u0435\u043C\u044F \u043D\u0430 \u0445\u043E\u0434",
              "\u041E\u0431\u044B\u0447\u043D\u043E \u0432\u0440\u0435\u043C\u044F \u043D\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043E. \u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u043F\u0435\u0440\u0435\u0434 \u043F\u0430\u0440\u0442\u0438\u0435\u0439 \u043C\u043E\u0436\u043D\u043E \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0442\u0430\u0439\u043C\u0435\u0440 \u043D\u0430 \u0432\u0435\u0441\u044C \u0445\u043E\u0434, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0432\u044B\u0431\u043E\u0440 \u0431\u0443\u043A\u0432\u044B \u0434\u043B\u044F \u043F\u0443\u0441\u0442\u043E\u0439 \u0444\u0438\u0448\u043A\u0438 \u0438 \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435\u043F\u0440\u0438\u043D\u044F\u0442\u044B\u0445 \u0441\u043B\u043E\u0432.",
              "\u041F\u043E \u0438\u0441\u0442\u0435\u0447\u0435\u043D\u0438\u0438 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0431\u0443\u043A\u0432\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0443, \u0430 \u0445\u043E\u0434 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u0430\u0441\u043E\u043C. \u041E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0448\u0442\u0440\u0430\u0444\u0430 \u0432 \u043E\u0447\u043A\u0430\u0445 \u0437\u0430 \u043F\u0440\u043E\u0441\u0440\u043E\u0447\u043A\u0443 \u043D\u0435\u0442."),
            rule_section(:personal, "\u041F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0430 \u0438 \u043E\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u043D\u0438\u0435 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u0438",
              "\u041F\u043E\u043A\u0430 \u0432\u044B \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0432\u044B\u043B\u043E\u0436\u0438\u043B\u0438, \u043A\u043B\u0430\u0432\u0438\u0448\u0430 I \u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0444\u0438\u0448\u0435\u043A: \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F, \u0430\u043B\u0444\u0430\u0432\u0438\u0442\u043D\u044B\u0439 \u0438\u043B\u0438 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0433\u043B\u0430\u0441\u043D\u044B\u0435. \u0426\u0438\u0444\u0440\u044B 1\u20137 \u0447\u0438\u0442\u0430\u044E\u0442 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043C\u0435\u0441\u0442\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438. Shift \u0441 \u0446\u0438\u0444\u0440\u043E\u0439 \u0441\u0440\u0430\u0437\u0443 \u043A\u043B\u0430\u0434\u0451\u0442 \u044D\u0442\u0443 \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "\u041D\u0430 \u043F\u043E\u043B\u0435 \u043C\u043E\u0436\u043D\u043E \u043D\u0430\u0431\u043B\u044E\u0434\u0430\u0442\u044C \u0431\u0443\u043A\u0432\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0434\u0440\u0443\u0433\u043E\u0439 \u0438\u0433\u0440\u043E\u043A \u0440\u0430\u0437\u043C\u0435\u0449\u0430\u0435\u0442 \u0435\u0449\u0451 \u0434\u043E \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F \u0441\u043B\u043E\u0432\u0430. \u0427\u0442\u043E\u0431\u044B \u0441\u043B\u044B\u0448\u0430\u0442\u044C \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u043E\u0431 \u0438\u0445 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0438 \u0438 \u0441\u043D\u044F\u0442\u0438\u0438, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Ctrl+P. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u0435 \u0432\u044B\u043A\u043B\u044E\u0447\u0438\u0442 \u044D\u0442\u0438 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u0442\u044C\u0441\u044F \u043F\u043E \u043F\u043E\u043B\u044E \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C\u0443 \u0441\u043F\u0438\u0441\u043A\u0443.",
              "Enter: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0438 \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0444\u0438\u0448\u043A\u0443; \u043F\u0440\u0438 \u043E\u0431\u043C\u0435\u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u043D\u044B\u0435 \u0444\u0438\u0448\u043A\u0438.",
              "Backspace: \u0441\u043D\u044F\u0442\u044C \u043D\u0435\u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043D\u043D\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u0441 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u043A\u043B\u0435\u0442\u043A\u0438.",
              "Z: \u0441\u043D\u044F\u0442\u044C \u0432\u0441\u0435 \u0444\u0438\u0448\u043A\u0438 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u0445\u043E\u0434\u0430.",
              "F: \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430.",
              "Y: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430 \u0438 \u043E\u0447\u043A\u0438 \u0431\u0435\u0437 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u0441\u043B\u043E\u0432\u0430\u0440\u044F.",
              "Escape: \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u0432\u044B\u0431\u043E\u0440 \u0444\u0438\u0448\u043A\u0438 \u0438\u043B\u0438 \u043E\u0431\u043C\u0435\u043D.",
              "C: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0443.",
              "I: \u0438\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0444\u0438\u0448\u0435\u043A, \u043F\u043E\u043A\u0430 \u0432\u044B\u043A\u043B\u0430\u0434\u043A\u0430 \u043D\u0435 \u043D\u0430\u0447\u0430\u0442\u0430.",
              "G: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0444\u0438\u0448\u043A\u0438 \u0434\u043B\u044F \u043E\u0431\u043C\u0435\u043D\u0430.",
              "\u041F\u0440\u043E\u0431\u0435\u043B \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u043E\u0431\u043C\u0435\u043D\u0430: \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u0444\u0438\u0448\u043A\u0443 \u0438\u043B\u0438 \u0441\u043D\u044F\u0442\u044C \u043E\u0442\u043C\u0435\u0442\u043A\u0443.",
              "P: \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u0442\u044C.",
              "E: \u0443\u0437\u043D\u0430\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u0444\u0438\u0448\u0435\u043A \u043D\u0430 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0430\u0445 \u0438 \u0432 \u043C\u0435\u0448\u043A\u0435.",
              "L: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0441\u043B\u043E\u0432\u0430.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0441\u0447\u0451\u0442.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.",
              "1: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u0435\u0440\u0432\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "2: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0432\u0442\u043E\u0440\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "3: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0442\u0440\u0435\u0442\u044C\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "4: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "5: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043F\u044F\u0442\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "6: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0448\u0435\u0441\u0442\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "7: \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0435\u0434\u044C\u043C\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043F\u043E\u0434\u0441\u0442\u0430\u0432\u043A\u0438.",
              "Shift+1: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u043F\u0435\u0440\u0432\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Shift+2: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0432\u0442\u043E\u0440\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Shift+3: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0442\u0440\u0435\u0442\u044C\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Shift+4: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Shift+5: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u043F\u044F\u0442\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Shift+6: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0448\u0435\u0441\u0442\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Shift+7: \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0441\u0435\u0434\u044C\u043C\u0443\u044E \u0444\u0438\u0448\u043A\u0443 \u043D\u0430 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443.",
              "Ctrl+P: \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F \u043E \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0438 \u0438 \u0441\u043D\u044F\u0442\u0438\u0438 \u0431\u0443\u043A\u0432.")
          ]
        end
      end
    end
    include GeneratedRulebook
  end
end
